const root = $json;

function collectNamedArrays(value, found = []) {
  if (!value || typeof value !== "object") return found;
  if (Array.isArray(value.questions)) found.push(value.questions);
  if (Array.isArray(value.urlParameters)) found.push(value.urlParameters);
  if (Array.isArray(value.calculations)) found.push(value.calculations);
  if (Array.isArray(value)) {
    for (const item of value) collectNamedArrays(item, found);
  } else {
    for (const item of Object.values(value)) collectNamedArrays(item, found);
  }
  return found;
}

const fields = {};
for (const list of collectNamedArrays(root)) {
  for (const item of list) {
    if (!item || !item.name) continue;
    fields[String(item.name).trim()] = item.value ?? "";
  }
}

function pick(...keys) {
  for (const key of keys) {
    const value = fields[key];
    if (value !== undefined && value !== null && String(value).trim() !== "") return String(value).trim();
  }
  return "";
}

function cleanNumber(value) {
  return String(value ?? "").replace(/[₹,%]/g, "").replace(/,/g, "").trim();
}

function yesNo(value) {
  const text = String(value ?? "").trim().toLowerCase();
  if (["true", "yes", "y", "1", "enabled", "active"].includes(text)) return "Yes";
  if (["false", "no", "n", "0", "disabled", "inactive"].includes(text)) return "No";
  return String(value ?? "").trim();
}

function asList(value) {
  if (Array.isArray(value)) return value.join(", ");
  return String(value ?? "").trim();
}

const spreadsheetId = pick("spreadsheet_id", "spreadsheetId", "Spreadsheet ID");
if (!spreadsheetId) {
  throw new Error(`Missing spreadsheet_id. Fields received by n8n: ${Object.keys(fields).join(", ")}`);
}

return {
  customer_id: pick("customer_id", "customerId", "Customer ID"),
  spreadsheet_id: spreadsheetId,
  tab_name: pick("tab_name", "tabName") || "Physical Gold",
  source: pick("source") || "wealthyo_dashboard_physical_gold_silver",
  category: pick("category", "Category") || "Gold",
  item: pick("item", "Item", "item_name", "Item Name", "ornament_name", "Ornament Name"),
  type: pick("type", "Type", "gold_type", "Gold Type"),
  weight_grams: cleanNumber(pick("weight_grams", "Weight Grams", "Weight in grams")),
  purity: pick("purity", "Purity"),
  purchase_date: pick("purchase_date", "Purchase Date", "date_of_purchase"),
  purchase_amount: cleanNumber(pick("purchase_amount", "Purchase Amount", "total_purchase_amount", "Total Purchase Amount")),
  bought_from: pick("bought_from", "Bought From", "Where did you buy?", "where_did_you_buy"),
  has_invoice: yesNo(pick("has_invoice", "Has Invoice")),
  making_charges: cleanNumber(pick("making_charges", "Making Charges")),
  gst_amount: cleanNumber(pick("gst_amount", "GST Amount")),
  certification_or_marking: asList(fields.certification_or_marking ?? fields["Certification or marking"] ?? fields["Certification / Marking"]),
  is_pledged: yesNo(pick("is_pledged", "Is Pledged"))
};
